async function telegram(env,method,body){
  for(let attempt=0;attempt<4;attempt++){
    const r=await fetch(`https://api.telegram.org/bot${env.BOT_TOKEN}/${method}`,{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify(body)});
    const data=await r.json();
    if(r.status===429 && attempt<3){
      const seconds=Math.max(1,Math.min(10,Number(data.parameters?.retry_after)||1));
      await new Promise(resolve=>setTimeout(resolve,seconds*1000));
      continue;
    }
    return data;
  }
}


function normalizeSearchText(text){
  return String(text || "")
    .toLowerCase()
    .replace(/ё/g,"е")
    .replace(/[^а-яa-z0-9]+/g," ")
    .trim();
}

// Простая русская лемматизация для поиска: сводим основные падежи,
// числа и формы слов к общей основе. Например: пирамида/пирамиды/
// пирамиду/пирамидами/пирамидах -> пирамид.
function stemRu(word){
  let w=word;
  if(w.length<4)return w;
  const suffixes=[
    "иями","ями","ами","ого","ему","ому","ее","ие","ые","ое","ей","ий","ый","ой",
    "иям","ия","ев","ов","ам","ем","ом","ах","ях","ию","ью","ию","ую","юю",
    "ою","ею","ая","яя","ое","ее","ые","ие","ым","им","ым","им","ых","их",
    "ую","юю","ую","юю","а","я","ы","и","е","о","у","ю","ь"
  ];
  for(const s of suffixes){
    if(w.length-s.length>=3 && w.endsWith(s)){
      w=w.slice(0,-s.length);
      break;
    }
  }
  return w;
}

function searchTokens(text){
  return normalizeSearchText(text)
    .split(/\s+/)
    .filter(Boolean)
    .map(stemRu);
}

function searchableText(...parts){
  return searchTokens(parts.join(" ")).join(" ");
}

function matchesSearch(query, ...parts){
  const tokens=searchTokens(query).filter(t=>t.length>=2);
  if(!tokens.length)return false;
  const haystack=searchableText(...parts);
  return tokens.every(token=>haystack.includes(token));
}

async function sendTextChunks(env,chat_id,text){
  // Telegram должен получать реальные переводы строк, а не буквальные \\n  // Последний слой нормализации защищает от двойного экранирования. 
  text=String(text||"").replace(/\\n/g,"\n");
  const parts=[];
  for(let i=0;i<text.length;i+=3900)parts.push(text.slice(i,i+3900));
  for(const part of parts)await telegram(env,"sendMessage",{chat_id,text:part,reply_markup:START_KEYBOARD});
}
function infoCodeForTask(n){
  return INFO_CODE.filter(([t])=>{
    const m=t.match(/^№(\d+)(?:\s*[-–—]\s*(\d+))?/);
    if(!m)return false;
    const a=Number(m[1]), b=m[2]?Number(m[2]):a;
    return n>=a && n<=b;
  });
}
function infoEscapeHtml(text){
  return String(text??"").replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;");
}

// Telegram HTML: <blockquote expandable> is a native collapsible quotation.
// Split at line boundaries instead of chopping up an HTML tag or a Python expression.
async function sendInfoProgram(env,chat_id,entry){
  const title=String(entry.title||"Программа");
  const theory=String(entry.lesson||"Подставь данные своего варианта и проверь условие отбора.");
  const source=String(entry.code||"");
  const lines=source.split("\n");
  const parts=[];
  let buf="";
  for(const line of lines){
    if(buf.length+line.length+1>2750 && buf){
      parts.push(buf);
      buf="";
    }
    buf+=(buf?"\n":"")+line;
  }
  if(buf)parts.push(buf);
  for(let i=0;i<parts.length;i++){
    const heading="<b>💻 "+infoEscapeHtml(title)+(parts.length>1?" (часть "+(i+1)+"/"+parts.length+")":"")+"</b>";
    const explanation=i===0?"\n\n<b>🧠 Разбор программы</b>\n"+infoEscapeHtml(theory)+"\n\n":"\n\n";
    const html=heading+explanation+"<blockquote expandable>"+infoEscapeHtml(parts[i])+"</blockquote>";
    const response=await telegram(env,"sendMessage",{chat_id,text:html,parse_mode:"HTML",reply_markup:START_KEYBOARD});
    if(!response?.ok){
      // Invalid entities should not prevent the user from receiving the code.
      await sendTextChunks(env,chat_id,title+"\n\n"+theory+"\n\n"+parts[i]);
    }
  }
}
