    if(infoContext){
      await telegram(env,"sendMessage",{chat_id,text:"❌ В информатике ничего не найдено.\\n\\nПопробуй №1–27 или тему: «черепаха», «turtle», «fnmatch», «маска», «рекурсия», «графы»."});
      return;
    }

        // Поиск по теме: отдаём сам материал, а не список совпадений.
    const byTitle=new Map(FORMULAS);
    const matchedFormulas=FORMULAS.filter(([title,body])=>
      matchesSearch(query,title,body)
    );
